window.RP_SESSION={"id":"S-1d2025619612","messages":[{"id":"RP-II-0122456","time":"2026-07-23T01:56:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"그 누구도 깨어있지 않을 밤.\n옆엔 잠들어있는 룸메이트, 스나가와 아이다가 눈에 들어왔다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122457","time":"2026-07-23T02:00:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"스윽 ㅡ, 거친 손과 부드러운 이불이 스치며 소리를 냈다.\n부엉이가 우는 소리가 저 너머에서 들려오는 듯 했다.\n\n천천히 몸을 일으키자, 열린 창문에서 바람이 쏴아아 ㅡ, 시원하게 불어왔다.\n불러도 오지 않던 친구들이 몰려드는 감각이 옅게나마 느껴졌지만...\n\n글쎄, 지금은 머리가 아팠다.\n끼이익, 방의 문을 조심스럽게 열었다.\n저벅저벅, 그 누구도 없는 길드의 어두운 복도를 걷기 시작했다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122458","time":"2026-07-23T02:02:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"탓, 탓.\n둔탁하게 계단을 내려가는 소리가 들려온다.\n무언가에 화가 난 듯, 답답한 듯.\n\n방출하지 못한 감정이 행동으로 드러났다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122459","time":"2026-07-23T02:03:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"1층의 문을 밀자, 밤공기가 훅 하고 밀려들었다.\n낮에는 그렇게 시끄럽던 마당이, 지금은 아무 소리도 나지 않는다.\n텃밭 쪽으로 몇 걸음. 그러다 방향을 틀어, 우물가에 앉았다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122460","time":"2026-07-23T02:03:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"두레박을 내릴 생각으로 온 것은 아니다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122461","time":"2026-07-23T02:04:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"그냥, 깊디 깊은 물 속을 내려다본다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122462","time":"2026-07-23T02:04:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"까맣고, 깊고, 그 무엇도 보이지 않는 어둠이 자리하고 있다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122463","time":"2026-07-23T02:05:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"낮에는 몇 번이고 지나쳤을 자리임에도, 이것이 매우 익숙하게 느껴지는 것은 내가 지금 느끼는 감정 탓일까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122464","time":"2026-07-23T02:05:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"아니면, 오늘 갔던 곳이 그랬기 때문일까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122465","time":"2026-07-23T02:06:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...하아.\"\n\n우물을 보던 것을 그만두고, 바닥에 털썩. 앉아버렸다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122466","time":"2026-07-23T02:06:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"포옥 ㅡ, 자신의 다리를 접어 무릎을 끌어안고 고개를 숙였다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122467","time":"2026-07-23T02:07:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"머릿 속에선, 하나의 순간이 반복적으로 플래시백 되고 있었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122468","time":"2026-07-23T02:08:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"코난, 소녀가 의뢰에 가도 되냐 넌지시 물어보았을 때, 간단히 허락해준 사람.","characters":["P-492692198c9a"]},{"id":"RP-II-0122469","time":"2026-07-23T02:08:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"그 사람이 하나의 아이를 지키려 자신의 모든 것을 불살라 곤충 때에 파묻혔을 때. 소녀는 손을 뻗었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122470","time":"2026-07-23T02:09:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"...물론, 금방 멈춰버렸다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122471","time":"2026-07-23T02:09:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"가늘고, 그 무엇도 쥐어본 적 없지만 약초를 캐고, 숲을 돌아다녀 투박했던 손.","characters":["P-492692198c9a"]},{"id":"RP-II-0122472","time":"2026-07-23T02:09:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"그 손을 바라본 순간, 멈췄던 이유는 죽는 게 무섭다. 같은 그런 일차원적인 이유가 아니었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122473","time":"2026-07-23T02:10:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"가봤자, 아무 소용도 없었으니까.\n정령이 없는 곳, 친구가 존재하지 않던 곳.\n그런 곳에서, 소녀는 한 없이 연약해져버렸다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122474","time":"2026-07-23T02:10:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...난.\"","characters":["P-492692198c9a"]},{"id":"RP-II-0122475","time":"2026-07-23T02:12:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...나는, 무엇을 위해 움직여야하는 걸까.\"","characters":["P-492692198c9a"]},{"id":"RP-II-0122476","time":"2026-07-23T02:12:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"조용히 내뱉는 자그마한 한탄이, 오늘따라 너무나 무겁게 느껴졌다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122477","time":"2026-07-23T02:14:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"평소엔 하지도 않던 고민. \n남에게는 늘 괜찮다고. 화나지 않았다고, 모르는 게 많다고.\n모두에게 매일같이 미소 짓던 소녀는, 조용히 울고 있었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122478","time":"2026-07-23T02:14:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":".","characters":["P-492692198c9a"]},{"id":"RP-II-0122479","time":"2026-07-23T02:14:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":".","characters":["P-492692198c9a"]},{"id":"RP-II-0122480","time":"2026-07-23T02:14:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":".","characters":["P-492692198c9a"]},{"id":"RP-II-0122481","time":"2026-07-23T02:14:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"얼마의 시간이 지났을까, 고개를 들었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122482","time":"2026-07-23T02:15:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"우물 아래, 아까는 보이지도 않던 것이 어렴풋하게 고개를 들고 있었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122483","time":"2026-07-23T02:16:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"물에 비친 것은, 울어버려 축축히 젖어버린 것만이 아니었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122484","time":"2026-07-23T02:16:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"물은, 많은 것을 보여준다.\n내면을 사람들은 호수라 표현하지 않던가.\n마음의 창이 되어주는 투명한 물이, 작게 속삭이는 소리가 들려왔다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122485","time":"2026-07-23T02:18:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「ㅡ 다 울었니?」","characters":["P-492692198c9a"]},{"id":"RP-II-0122486","time":"2026-07-23T02:19:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「너 하나 때문에, 이 내가 바보같이 기다려야했잖아.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122487","time":"2026-07-23T02:20:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"무심한 목소리, 그 속에 작은 한숨이 섞여들어갔다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122488","time":"2026-07-23T02:21:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그래서, 뭐라도 좀 바뀌었을까?」","characters":["P-492692198c9a"]},{"id":"RP-II-0122489","time":"2026-07-23T02:21:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「무릎에 얼굴 쳐박고, 훌쩍인다고 무언가가 바뀔 거라 생각한 건 아니지?」","characters":["P-492692198c9a"]},{"id":"RP-II-0122490","time":"2026-07-23T02:21:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「난, 내가 사랑해 마지 않는 친구가 그러길 바라진 않는데.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122491","time":"2026-07-23T02:22:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...평소엔 안 나타나더니.\"\n\n그래, 과거를 잠시 생각해보자.\n부모가, 어머니가 떠나라 했던 그 날을.","characters":["P-492692198c9a"]},{"id":"RP-II-0122492","time":"2026-07-23T02:23:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"비가 오던 그 날, 숲으로 도망치듯 들어와 훌쩍이던 소녀를 달래주던 것이 있었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122493","time":"2026-07-23T02:24:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"다 젖어 얼굴에 눌러붙은 머릿결을 부드럽게 넘겨주던 따스하고도 애잔한 손길이 있었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122494","time":"2026-07-23T02:24:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"그 날을 제외하곤, 한 번도 나타나지 않던 정령이 지금에 와서야 등장했다는 것은, 무슨 의미를 지니고 있을까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122495","time":"2026-07-23T02:24:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「어째, 달라진 게 없네.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122496","time":"2026-07-23T02:25:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「예전이나 지금이나, ...사람을 미워하지 못해서 문제였지. 너는.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122497","time":"2026-07-23T02:25:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"물결이 그리는 결을 따라, 머릿 속에 내리꽃히는 목소리가 소녀의 호수에 파문을 일으켰다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122498","time":"2026-07-23T02:26:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그런다고, 사람들은 좋아하지 않는다는 걸. 넌 몰라.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122499","time":"2026-07-23T02:27:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「남이 부탁하면 다 하려들고, 다치면 뛰어들고, 무엇이든 챙겨주려 들고.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122500","time":"2026-07-23T02:27:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그러면서도, 바라는 게 없어버리면 어쩌자는 건지.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122501","time":"2026-07-23T02:28:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「너 ㅡ, 한번이라도 네가 뭘 하고 싶은지 말해봤어?」","characters":["P-492692198c9a"]},{"id":"RP-II-0122502","time":"2026-07-23T02:29:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n입이 열개라도, 그 어떠한 말도 나오지 못했다.\n성인이 되어서야 만난 인연에 너무나 취해버렸기 때문일까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122503","time":"2026-07-23T02:30:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「...봐, 또 그러잖아.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122504","time":"2026-07-23T02:30:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「불리하면, 입 다물고 피해. ...넌, 항상 그래.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122505","time":"2026-07-23T02:30:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「말하면 상대가 부담스러워할까 봐, 먼저 삼키는 거지.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122506","time":"2026-07-23T02:30:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그날도.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122507","time":"2026-07-23T02:31:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「쫓겨나면서, 한 마디도 안 하고 나오질 않나. 왜냐고 묻지도, 싫다고 말하지도 않고 홀로 젖어있질 않나.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122508","time":"2026-07-23T02:31:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「혼자 다 짊어지고, 혼자 못 했다고 자책하고.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122509","time":"2026-07-23T02:31:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「ㅡ 참, 한결같아서 짜증나.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122510","time":"2026-07-23T02:31:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「다 울었으면, 하나만 대답해.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122511","time":"2026-07-23T02:32:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「ㅡ 너, 뭐가 되고 싶어?」","characters":["P-492692198c9a"]},{"id":"RP-II-0122512","time":"2026-07-23T02:32:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「'모두가 기뻐하면 좋잖아요' 나, '도와드리고 싶어서요' 같은 대답할 거면, 하지 마.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122513","time":"2026-07-23T02:33:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n계속되는 대화에, 우울해진 소녀는 그리 말하는 녀석의 시선을 피해 하늘로 시선을 옮겼다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122514","time":"2026-07-23T02:34:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"한참의 시간이 지나고, 아주 작게 중얼거렸다.\n\"ㅡ...지키고 싶어.\"","characters":["P-492692198c9a"]},{"id":"RP-II-0122515","time":"2026-07-23T02:34:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"이 곳에서 쌓아갈, 하나 뿐인 추억을.\"","characters":["P-492692198c9a"]},{"id":"RP-II-0122516","time":"2026-07-23T02:34:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「...」","characters":["P-492692198c9a"]},{"id":"RP-II-0122517","time":"2026-07-23T02:35:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"소녀의 말이 잔잔하게 우물에 파문을 일으키자, 주위는 확 조용해졌다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122518","time":"2026-07-23T02:35:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"파문이 점점 옅어지는 순간, 피식 ㅡ, 하고 웃는 소리가 들려왔다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122519","time":"2026-07-23T02:35:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「ㅡ 그래.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122520","time":"2026-07-23T02:36:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그거면 됐어.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122521","time":"2026-07-23T02:36:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「거창하지도 않고, 남 얘기도 아닌 네 얘기가 그거라면.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122522","time":"2026-07-23T02:36:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...대체, 무슨 말을 하는 거야.\"","characters":["P-492692198c9a"]},{"id":"RP-II-0122523","time":"2026-07-23T02:37:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「글쎄.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122524","time":"2026-07-23T02:37:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「말해두는데, 나는 매정한 정령이야.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122525","time":"2026-07-23T02:37:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「울면, 또 바보같이 운다고 놀릴거고.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122526","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「도망치면, 멍청한 녀석이라고, 무지한 녀석이라고. 말해버릴거야.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122527","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그래도 괜찮다면 ㅡ...」","characters":["P-492692198c9a"]},{"id":"RP-II-0122528","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「손 줘봐.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122529","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"\"...어?\"\n\n그 말이 무슨 소리인지조차 인지하지 못한 소녀는, 천천히 손을 뻗었다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122530","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"무의식적으로, ...또는 의식적으로.","characters":["P-492692198c9a"]},{"id":"RP-II-0122531","time":"2026-07-23T02:38:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"홀린 사람처럼, 정령에게로 손을 뻗은 그 순간이었을까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122532","time":"2026-07-23T02:39:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「축하해.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122533","time":"2026-07-23T02:40:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"물이 천천히 차오르기 시작한다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122534","time":"2026-07-23T02:40:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"두레박도 없고, 밀어 올리는 기구도 없는데, 어떻게 차오르는 걸까.","characters":["P-492692198c9a"]},{"id":"RP-II-0122535","time":"2026-07-23T02:40:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"손끝이 마중 나오듯 차오른 물은, 에스페의 손을 적셨다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122536","time":"2026-07-23T02:41:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「이제, 혼자 냅두지 않을게.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122537","time":"2026-07-23T02:41:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「그러니까.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122538","time":"2026-07-23T02:41:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"「너 하고 싶은대로 살아봐.」","characters":["P-492692198c9a"]},{"id":"RP-II-0122539","time":"2026-07-23T02:41:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"...화아아 ㅡ, 물의 정령이 우물 밖으로 나와 소녀의 주변을 맴돌았다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122540","time":"2026-07-23T02:42:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"두둥실 떠오른 것이 ㅡ, 소녀의 내면을 작게나마 바꿔놓았다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122541","time":"2026-07-23T02:42:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"...어느샌가, 하늘이 밝아오기 시작하면.","characters":["P-492692198c9a"]},{"id":"RP-II-0122542","time":"2026-07-23T02:43:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"소녀의 삶은, 새로워질테다.","characters":["P-492692198c9a"]},{"id":"RP-II-0122543","time":"2026-07-23T02:43:00+09:00","room":"RP II","name":"에스페 / 물의 정령","profile":"에스페","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-492692198c9a"]},{"id":"RP-II-0122544","time":"2026-07-23T02:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
